@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun RecordVisitScreen(
    patient: PatientInfo,
    dangerSignOptions: List<DangerSignOption>,
    isSaving: Boolean,
    saveErrorMessage: String?,
    onBack: () -> Unit,
    onSaveVisit: (
        visitDate: String,
        gestationalAgeWeeks: Int?,
        weightKg: Double?,
        systolicBp: Int?,
        diastolicBp: Int?,
        dangerSigns: List<DangerSignOption>,
        notes: String?
    ) -> Unit
) {
    val today = remember { LocalDate.now() }
    var visitDate by remember { mutableStateOf(today.toString()) }
    var gestationalAgeText by remember {
        mutableStateOf(patient.gestationalAgeWeeks?.toString() ?: "")
    }
    var weightText by remember { mutableStateOf("") }
    var systolicBpText by remember { mutableStateOf("") }
    var diastolicBpText by remember { mutableStateOf("") }

    // Danger signs state: Set of selected codes
    var selectedDangerCodes by remember {
        mutableStateOf(setOf("none"))
    }

    var notesText by remember { mutableStateOf("") }
    var showDatePicker by remember { mutableStateOf(false) }
    var validationError by remember { mutableStateOf<String?>(null) }

    val snackbarHostState = remember { SnackbarHostState() }
    val scope = rememberCoroutineScope()

    if (showDatePicker) {
        val datePickerState = rememberDatePickerState(
            initialSelectedDateMillis = System.currentTimeMillis()
        )
        val confirmEnabled by remember {
            derivedStateOf { datePickerState.selectedDateMillis != null }
        }

        DatePickerDialog(
            onDismissRequest = { showDatePicker = false },
            confirmButton = {
                TextButton(
                    onClick = {
                        datePickerState.selectedDateMillis?.let { millis ->
                            val picked = Instant.ofEpochMilli(millis)
                                .atZone(ZoneId.systemDefault())
                                .toLocalDate()
                            visitDate = picked.toString()
                        }
                        showDatePicker = false
                    },
                    enabled = confirmEnabled
                ) {
                    Text("OK")
                }
            },
            dismissButton = {
                TextButton(onClick = { showDatePicker = false }) {
                    Text("Cancel")
                }
            }
        ) {
            DatePicker(state = datePickerState)
        }
    }

    Scaffold(
        snackbarHost = { SnackbarHost(snackbarHostState) },
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            text = "Record ANC Visit",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = patient.fullName,
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onPrimaryContainer
                        )
                    }
                },
                navigationIcon = {
                    IconButton(onClick = onBack, enabled = !isSaving) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back"
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer
                )
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Patient info header card
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant
                ),
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Patient: ${patient.fullName}",
                        style = MaterialTheme.typography.bodyMedium,
                        fontWeight = FontWeight.Bold
                    )
                    patient.edd?.let {
                        Text(
                            text = "EDD: $it",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }

            // Error alert if saving failed
            if (saveErrorMessage != null) {
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.errorContainer
                    ),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = saveErrorMessage,
                        color = MaterialTheme.colorScheme.onErrorContainer,
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.padding(12.dp)
                    )
                }
            }

            if (validationError != null) {
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.errorContainer
                    ),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = validationError ?: "",
                        color = MaterialTheme.colorScheme.onErrorContainer,
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.padding(12.dp)
                    )
                }
            }

            // 1. Visit Date
            Text(
                text = "Visit Information",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold
            )

            OutlinedTextField(
                value = visitDate,
                onValueChange = { visitDate = it },
                label = { Text("Visit Date (YYYY-MM-DD) *") },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                trailingIcon = {
                    IconButton(onClick = { showDatePicker = true }) {
                        Icon(
                            imageVector = Icons.Default.CalendarMonth,
                            contentDescription = "Pick date"
                        )
                    }
                }
            )

            // 2. Gestational Age (weeks)
            OutlinedTextField(
                value = gestationalAgeText,
                onValueChange = { gestationalAgeText = it.filter { ch -> ch.isDigit() } },
                label = { Text("Gestational Age (weeks)") },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                supportingText = { Text("Weeks of pregnancy at visit") }
            )

            HorizontalDivider()

            // 3. Vital Signs Section
            Text(
                text = "Vital Signs",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold
            )

            // Weight (kg)
            OutlinedTextField(
                value = weightText,
                onValueChange = { weightText = it },
                label = { Text("Weight (kg)") },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                suffix = { Text("kg") }
            )

            // Blood pressure: Systolic / Diastolic
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                OutlinedTextField(
                    value = systolicBpText,
                    onValueChange = { systolicBpText = it.filter { ch -> ch.isDigit() } },
                    label = { Text("Systolic BP") },
                    modifier = Modifier.weight(1f),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    suffix = { Text("mmHg") }
                )
                OutlinedTextField(
                    value = diastolicBpText,
                    onValueChange = { diastolicBpText = it.filter { ch -> ch.isDigit() } },
                    label = { Text("Diastolic BP") },
                    modifier = Modifier.weight(1f),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    suffix = { Text("mmHg") }
                )
            }

            HorizontalDivider()

            // 4. Danger Signs Present (multiple allowed)
            Text(
                text = "Danger Signs Present",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold
            )
            Text(
                text = "Select all danger signs observed, or 'None'.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            FlowRow(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                for (option in dangerSignOptions) {
                    val isSelected = selectedDangerCodes.contains(option.code)
                    FilterChip(
                        selected = isSelected,
                        onClick = {
                            if (option.code == "none") {
                                selectedDangerCodes = if (isSelected) emptySet() else setOf("none")
                            } else {
                                val current = selectedDangerCodes.toMutableSet()
                                current.remove("none")
                                if (isSelected) {
                                    current.remove(option.code)
                                    if (current.isEmpty()) current.add("none")
                                } else {
                                    current.add(option.code)
                                }
                                selectedDangerCodes = current
                            }
                        },
                        label = { Text(option.display) },
                        leadingIcon = if (isSelected) {
                            {
                                Icon(
                                    imageVector = Icons.Default.Check,
                                    contentDescription = null,
                                    modifier = Modifier.size(FilterChipDefaults.IconSize)
                                )
                            }
                        } else null,
                        colors = if (option.code != "none" && isSelected) {
                            FilterChipDefaults.filterChipColors(
                                selectedContainerColor = MaterialTheme.colorScheme.errorContainer,
                                selectedLabelColor = MaterialTheme.colorScheme.onErrorContainer
                            )
                        } else {
                            FilterChipDefaults.filterChipColors()
                        }
                    )
                }
            }

            HorizontalDivider()

            // 5. Free-text notes
            Text(
                text = "Clinical Notes",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold
            )

            OutlinedTextField(
                value = notesText,
                onValueChange = { notesText = it },
                label = { Text("Free-text notes") },
                placeholder = { Text("Add any notes, complaints, or instructions...") },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(120.dp),
                maxLines = 5
            )

            Spacer(modifier = Modifier.height(8.dp))

            // Action Buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                OutlinedButton(
                    onClick = onBack,
                    modifier = Modifier.weight(1f),
                    enabled = !isSaving
                ) {
                    Text("Cancel")
                }

                Button(
                    onClick = {
                        validationError = null
                        val vDate = visitDate.trim()
                        if (vDate.isBlank()) {
                            validationError = "Please enter a valid visit date (YYYY-MM-DD)."
                            return@Button
                        }
                        try {
                            LocalDate.parse(vDate.substring(0, 10))
                        } catch (e: Exception) {
                            validationError = "Invalid date format. Expected YYYY-MM-DD."
                            return@Button
                        }

                        val ga = gestationalAgeText.trim().toIntOrNull()
                        val weight = weightText.trim().toDoubleOrNull()
                        val sys = systolicBpText.trim().toIntOrNull()
                        val dia = diastolicBpText.trim().toIntOrNull()

                        if (weightText.isNotBlank() && weight == null) {
                            validationError = "Please enter a valid decimal for weight."
                            return@Button
                        }
                        if (systolicBpText.isNotBlank() && sys == null) {
                            validationError = "Please enter a valid number for systolic BP."
                            return@Button
                        }
                        if (diastolicBpText.isNotBlank() && dia == null) {
                            validationError = "Please enter a valid number for diastolic BP."
                            return@Button
                        }

                        val selectedOptions = dangerSignOptions.filter {
                            selectedDangerCodes.contains(it.code)
                        }

                        onSaveVisit(
                            vDate,
                            ga,
                            weight,
                            sys,
                            dia,
                            selectedOptions,
                            notesText.ifBlank { null }
                        )
                    },
                    modifier = Modifier.weight(1f),
                    enabled = !isSaving
                ) {
                    if (isSaving) {
                        CircularProgressIndicator(
                            modifier = Modifier.size(20.dp),
                            color = MaterialTheme.colorScheme.onPrimary,
                            strokeWidth = 2.dp
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Saving...")
                    } else {
                        Icon(Icons.Default.Save, contentDescription = null)
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Save Visit")
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

package com.example.ancapp.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.AncVisit
import com.example.ancapp.data.DangerSignOption
import com.example.ancapp.data.PatientInfo
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

sealed interface CurrentScreen {
    data object Register : CurrentScreen
    data class PatientDetail(val patient: PatientInfo) : CurrentScreen
    data class RecordVisit(val patient: PatientInfo) : CurrentScreen
}

data class AncUiState(
    val currentScreen: CurrentScreen = CurrentScreen.Register,
    val patients: List<PatientInfo> = emptyList(),
    val isPatientsLoading: Boolean = false,
    val patientsError: String? = null,
    val selectedPatient: PatientInfo? = null,
    val visits: List<AncVisit> = emptyList(),
    val isVisitsLoading: Boolean = false,
    val visitsError: String? = null,
    val dangerSignOptions: List<DangerSignOption> = emptyList(),
    val isSavingVisit: Boolean = false,
    val saveVisitError: String? = null
)

class AncViewModel(
    private val repository: AncRepository = AncRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow(AncUiState())
    val uiState: StateFlow<AncUiState> = _uiState.asStateFlow()

    init {
        loadPatients()
        loadDangerSigns()
    }

    fun loadPatients(forceRefresh: Boolean = false) {
        viewModelScope.launch {
            _uiState.update { it.copy(isPatientsLoading = true, patientsError = null) }
            try {
                val list = repository.getPatients(forceRefresh = forceRefresh)
                _uiState.update {
                    it.copy(
                        patients = list,
                        isPatientsLoading = false,
                        patientsError = null
                    )
                }
            } catch (e: Exception) {
                _uiState.update {
                    it.copy(
                        isPatientsLoading = false,
                        patientsError = e.message ?: "Failed to load patients"
                    )
                }
            }
        }
    }

    private fun loadDangerSigns() {
        viewModelScope.launch {
            val options = repository.getDangerSignOptions()
            _uiState.update { it.copy(dangerSignOptions = options) }
        }
    }

    fun selectPatient(patient: PatientInfo) {
        _uiState.update {
            it.copy(
                selectedPatient = patient,
                currentScreen = CurrentScreen.PatientDetail(patient),
                visits = emptyList(),
                visitsError = null
            )
        }
        loadVisits(patient.id)
    }

    fun loadVisits(patientId: String) {
        viewModelScope.launch {
            _uiState.update { it.copy(isVisitsLoading = true, visitsError = null) }
            try {
                val visits = repository.getVisitsForPatient(patientId)
                _uiState.update {
                    it.copy(
                        visits = visits,
                        isVisitsLoading = false,
                        visitsError = null
                    )
                }
            } catch (e: Exception) {
                _uiState.update {
                    it.copy(
                        isVisitsLoading = false,
                        visitsError = e.message ?: "Failed to load visits"
                    )
                }
            }
        }
    }

    fun openRecordVisit() {
        val patient = _uiState.value.selectedPatient ?: return
        _uiState.update {
            it.copy(
                currentScreen = CurrentScreen.RecordVisit(patient),
                saveVisitError = null
            )
        }
    }

    fun navigateBack(): Boolean {
        val current = _uiState.value.currentScreen
        return when (current) {
            is CurrentScreen.RecordVisit -> {
                _uiState.update {
                    it.copy(
                        currentScreen = CurrentScreen.PatientDetail(current.patient),
                        saveVisitError = null
                    )
                }
                true
            }
            is CurrentScreen.PatientDetail -> {
                _uiState.update {
                    it.copy(
                        currentScreen = CurrentScreen.Register,
                        selectedPatient = null
                    )
                }
                true
            }
            is CurrentScreen.Register -> false
        }
    }

    fun saveVisit(
        visitDate: String,
        gestationalAgeWeeks: Int?,
        weightKg: Double?,
        systolicBp: Int?,
        diastolicBp: Int?,
        dangerSigns: List<DangerSignOption>,
        notes: String?
    ) {
        val patient = _uiState.value.selectedPatient ?: return
        viewModelScope.launch {
            _uiState.update { it.copy(isSavingVisit = true, saveVisitError = null) }
            val result = repository.saveVisit(
                patientId = patient.id,
                visitDate = visitDate,
                gestationalAgeWeeks = gestationalAgeWeeks,
                weightKg = weightKg,
                systolicBp = systolicBp,
                diastolicBp = diastolicBp,
                dangerSigns = dangerSigns,
                notes = notes
            )
            result.fold(
                onSuccess = {
                    // Refresh visits from server so new visit is included
                    val updatedVisits = try {
                        repository.getVisitsForPatient(patient.id)
                    } catch (_: Exception) {
                        _uiState.value.visits
                    }
                    _uiState.update {
                        it.copy(
                            isSavingVisit = false,
                            saveVisitError = null,
                            visits = updatedVisits,
                            currentScreen = CurrentScreen.PatientDetail(patient)
                        )
                    }
                },
                onFailure = { err ->
                    _uiState.update {
                        it.copy(
                            isSavingVisit = false,
                            saveVisitError = err.message ?: "Failed to save visit"
                        )
                    }
                }
            )
        }
    }
}

